def copy_old_themes():
    """L'ancien champ texte « theme » devient un thème lié au projet (doublons fusionnés), sans perte."""
    connection = op.get_bind()
    theme = sa.table('theme', sa.column('id'), sa.column('name'), sa.column('normalized_name'), sa.column('active'))
    link = sa.table('project_theme', sa.column('project_id'), sa.column('theme_id'))
    ids = {}
    for project_id, old in connection.execute(sa.text("SELECT id, theme FROM project WHERE theme IS NOT NULL")):
        name = " ".join(old.split())
        normalized = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode().lower()
        if not normalized:
            continue
        if normalized not in ids:
            connection.execute(theme.insert().values(name=name, normalized_name=normalized, active=True))
            ids[normalized] = connection.execute(
                sa.select(theme.c.id).where(theme.c.normalized_name == normalized)).scalar()
        connection.execute(link.insert().values(project_id=project_id, theme_id=ids[normalized]))


